-- ----------------------------
-- Table structure for agent_analyses
-- ----------------------------
DROP TABLE IF EXISTS "public"."agent_analyses";
CREATE TABLE "public"."agent_analyses" (
  "id" int8 NOT NULL DEFAULT nextval('agent_analyses_id_seq'::regclass),
  "created_at" timestamptz(6) NOT NULL DEFAULT now(),
  "trade_date" date,
  "session" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'intraday'::text,
  "trigger" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'interval'::text,
  "model" text COLLATE "pg_catalog"."default",
  "status" text COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'ok'::text,
  "summary" text COLLATE "pg_catalog"."default",
  "market_view" text COLLATE "pg_catalog"."default",
  "confidence" numeric,
  "picks_count" int4 NOT NULL DEFAULT 0,
  "rounds" int4 NOT NULL DEFAULT 0,
  "tool_calls" int4 NOT NULL DEFAULT 0,
  "latency_ms" int4,
  "prompt_summary" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "raw_response" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "usage" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "error" text COLLATE "pg_catalog"."default"
)
;

